const items = $input.all();
const results = [];
const activityLinePattern = /actively hiring|actively recruiting|alumni|alum$/i;

const germanRequirementPhrases = [
  "fließend deutsch",
  "sehr gute deutschkenntnisse",
  "gute deutschkenntnisse",
  "gute kenntnisse in deutsch",
  "deutsch als muttersprache",
  "muttersprachliches deutsch",
  "verhandlungssicheres deutsch",
  "deutschkenntnisse zwingend",
  "deutsch c1",
  "deutsch c2"
];

function getPositionType(title) {
  const t = title.toLowerCase();
  if (t.includes('werkstudent') || t.includes('working student')) return 'Working Student';
  if (t.includes('praktikant') || t.includes('internship') || /\bintern\b/.test(t)) return 'Intern';
  return null;
}

for (const item of items) {
  const text = item.json.text;
  const isLinkedIn = item.json.from.value[0].address.includes('linkedin.com');
  const isIndeed = item.json.from.value[0].address.includes('indeed.com');

  const candidates = [];

  if (isLinkedIn) {
    const blocks = text.split('---------------------------------------------------------');
    for (const block of blocks) {
      const lines = block.trim().split('\n').filter(l => l.trim());
      const linkMatch = block.match(/View job: (https:\/\/[^\s]+)/);
      if (!linkMatch) continue;

      const viewJobIdx = lines.findIndex(l => l.startsWith('View job:'));
      if (viewJobIdx < 3) continue;

      let idx = viewJobIdx - 1;
      if (activityLinePattern.test(lines[idx])) idx--;

      const location = lines[idx];
      const company = lines[idx - 1];
      const title = lines[idx - 2];
      if (!title || !company || !location) continue;

      candidates.push({
        title: title.trim(),
        company: company.trim(),
        location: location.trim(),
        link: linkMatch[1],
        description: block
      });
    }
  }

  if (isIndeed) {
    const blocks = text.split('\n\n').filter(b => b.trim());
    for (const block of blocks) {
      const lines = block.trim().split('\n').filter(l => l.trim());
      if (lines.length < 3) continue;

      const linkLine = lines.find(l => l.startsWith('https://'));
      if (!linkLine || linkLine.includes('/pagead/')) continue;

      const companyLocation = lines[1]?.split(' - ') || [];

      candidates.push({
        title: lines[0].trim(),
        company: companyLocation[0]?.trim() || '',
        location: companyLocation[1]?.trim() || '',
        link: linkLine,
        description: block
      });
    }
  }

  for (const c of candidates) {
    const positionType = getPositionType(c.title);
    if (!positionType) continue;

    const desc = c.description.toLowerCase();
    const hasStrictGermanReq = germanRequirementPhrases.some(p => desc.includes(p));
    if (hasStrictGermanReq) continue;

    results.push({
      json: {
        company: c.company,
        position: positionType,
        title: c.title,
        location: c.location,
        link: c.link
      }
    });
  }
}

return results;

const items = $input.all();
const seen = new Set();
const results = [];

function getJobKey(link) {
  const linkedInMatch = link.match(/\/jobs\/view\/(\d+)/);
  if (linkedInMatch) return `li_${linkedInMatch[1]}`;

  const indeedMatch = link.match(/[?&]jk=([a-zA-Z0-9]+)/);
  if (indeedMatch) return `in_${indeedMatch[1]}`;

  return null;
}

for (const item of items) {
  const { title, company, link } = item.json;

  let key = getJobKey(link);
  if (!key) {
    key = `${title}|${company}`.toLowerCase().trim();
  }

  if (seen.has(key)) continue;
  seen.add(key);

  results.push(item);
}

return results;
